package pe.nexo.store.product;import jakarta.persistence.LockModeType;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.util.*;public interface ProductRepository extends JpaRepository<Product,Long>{List<Product>findByOriginalPriceIsNotNull();List<Product>findByCategoryIgnoreCase(String category);boolean existsBySkuIgnoreCase(String sku);boolean existsBySkuIgnoreCaseAndIdNot(String sku,Long id);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select p from Product p where p.id=:id")Optional<Product>findByIdForUpdate(@Param("id")Long id);}
